// @vitest-environment node
import { afterEach, describe, expect, it, vi } from "vitest";

vi.mock("server-only", () => ({}));

// A fresh module each time, because getServerEnv caches its result.
async function loadGetServerEnv() {
  vi.resetModules();
  const serverEnvModule = await import("./server");
  return serverEnvModule.getServerEnv;
}

function errorMessageOf(run: () => unknown): string {
  try {
    run();
  } catch (error) {
    return (error as Error).message;
  }
  return "";
}

describe("getServerEnv", () => {
  afterEach(() => {
    vi.unstubAllEnvs();
  });

  it("returns the pooled database connection string", async () => {
    vi.stubEnv("DATABASE_URL", "postgresql://user:secret@ep-example-pooler.neon.tech/db");
    const getServerEnv = await loadGetServerEnv();

    expect(getServerEnv().DATABASE_URL).toBe(
      "postgresql://user:secret@ep-example-pooler.neon.tech/db",
    );
  });

  it("names a missing variable", async () => {
    vi.stubEnv("DATABASE_URL", "");
    const getServerEnv = await loadGetServerEnv();

    const message = errorMessageOf(getServerEnv);
    expect(message).toContain("DATABASE_URL");
    expect(message).toContain(".env.local.example");
    expect(message).toContain(".env.production.example");
  });

  it("rejects a value that is not a PostgreSQL URL without echoing the value", async () => {
    vi.stubEnv("DATABASE_URL", "https://secret-value.example.com");
    const getServerEnv = await loadGetServerEnv();

    const message = errorMessageOf(getServerEnv);
    expect(message).toContain("DATABASE_URL");
    expect(message).not.toContain("secret-value");
  });
});

describe("getDeviceEnv", () => {
  afterEach(() => vi.unstubAllEnvs());
  it("accepts a canonical encoding of 32 developer-generated bytes", async () => {
    vi.stubEnv("DEVICE_AUTH_SECRET", Buffer.alloc(32, 7).toString("base64url"));
    vi.stubEnv("NODE_ENV", "test"); vi.stubEnv("DEVICE_IP_SOURCE", "unconfigured"); vi.stubEnv("VERCEL", undefined);
    const { getDeviceEnv } = await import("./server");
    expect(getDeviceEnv().DEVICE_IP_SOURCE).toBe("unconfigured");
  });
  it("rejects missing or low-entropy-size key material without echoing its value", async () => {
    vi.stubEnv("DEVICE_AUTH_SECRET", "too-short-test-placeholder");
    const { getDeviceEnv } = await import("./server");
    const message = errorMessageOf(getDeviceEnv);
    expect(message).toContain("DEVICE_AUTH_SECRET");
    expect(message).toContain(".env.local.example");
    expect(message).toContain(".env.production.example");
    expect(message).not.toContain("too-short-test-placeholder");
  });
});

describe("lazy Sandbox-only payment configuration", () => {
	afterEach(() => vi.unstubAllEnvs());
	function configure() {
		vi.stubEnv("NEXT_PUBLIC_PAYPAL_CLIENT_ID", "fictional_sandbox_client_id_123456");
		vi.stubEnv("PAYPAL_CLIENT_ID", "fictional_sandbox_client_id_123456");
		vi.stubEnv("PAYPAL_CLIENT_SECRET", "fictional_sandbox_secret_123456");
		vi.stubEnv("PAYPAL_ENVIRONMENT", "sandbox");
		vi.stubEnv("PAYPAL_BUYER_APPROVAL_ENABLED", "false");
		vi.stubEnv("PAYPAL_WEBHOOK_ID", undefined);
	}
	it("requires matching app IDs and Sandbox, defaulting buyer approval to disabled", async () => {
		configure();
		const { getPayPalEnv } = await import("./server");
		expect(getPayPalEnv().PAYPAL_ENVIRONMENT).toBe("sandbox");
		expect(getPayPalEnv().PAYPAL_BUYER_APPROVAL_ENABLED).toBe("false");
		vi.stubEnv("PAYPAL_BUYER_APPROVAL_ENABLED", undefined);
		expect(getPayPalEnv().PAYPAL_BUYER_APPROVAL_ENABLED).toBe("false");
	});
	it.each(["PAYPAL_CLIENT_ID", "PAYPAL_CLIENT_SECRET", "NEXT_PUBLIC_PAYPAL_CLIENT_ID", "PAYPAL_ENVIRONMENT", "PAYPAL_BUYER_APPROVAL_ENABLED"])(
		"fails closed for invalid %s without exposing values", async (name) => {
			configure();
			const value = name === "PAYPAL_ENVIRONMENT" ? "production" : name === "PAYPAL_BUYER_APPROVAL_ENABLED" ? "true" : "private_invalid_credential";
			vi.stubEnv(name, value);
			// A well-shaped but incorrect secret cannot be distinguished locally; use a missing one.
			if (name === "PAYPAL_CLIENT_SECRET") vi.stubEnv(name, "");
			const { getPayPalEnv } = await import("./server");
			const message = errorMessageOf(getPayPalEnv);
			expect(message).toMatch(/^Missing or invalid PayPal environment variables: [A-Z_]+(?:, [A-Z_]+)*\. See \.env\.local\.example or \.env\.production\.example\.$/);
			// "production" is part of the public template filename, not an echoed value.
			const diagnostic = message.replace(". See .env.local.example or .env.production.example.", "");
			expect(diagnostic).not.toContain(value);
		});
	it("does not validate payment credentials when unrelated database configuration is used", async () => {
		vi.stubEnv("PAYPAL_CLIENT_SECRET", "");
		vi.stubEnv("DATABASE_URL", "postgresql://fictional:fictional@localhost/test");
		const getServerEnv = await loadGetServerEnv();
		expect(getServerEnv().DATABASE_URL).toContain("localhost/test");
	});
	it("enables approval only with matching Sandbox credentials and a registered webhook ID", async () => {
		configure();
		vi.stubEnv("PAYPAL_BUYER_APPROVAL_ENABLED", "true");
		vi.stubEnv("PAYPAL_WEBHOOK_ID", "FICTIONAL123WEBHOOK");
		const { getPayPalEnv } = await import("./server");
		expect(getPayPalEnv().PAYPAL_BUYER_APPROVAL_ENABLED).toBe("true");
		vi.stubEnv("PAYPAL_WEBHOOK_ID", "replace_with_webhook");
		expect(getPayPalEnv).toThrow(/PAYPAL_WEBHOOK_ID/);
	});
});
